def highest_score(pairs):
    if not pairs:
        return {}

    result = {}
    order = []  # to preserve first appearance order

    for name, score in pairs:
        if name not in result:
            result[name] = score
            order.append(name)
        else:
            result[name] = max(result[name], score)

    return {name: result[name] for name in order}
